function onesMinusZeros(grid) {
  const m = grid.length;
  const n = grid[0].length;
  const rowOnes = new Array(m).fill(0);
  const colOnes = new Array(n).fill(0);
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      rowOnes[i] += grid[i][j];
      colOnes[j] += grid[i][j];
    }
  }
  const diff = [];
  for (let i = 0; i < m; i++) {
    const row = [];
    for (let j = 0; j < n; j++) {
      row.push(2 * rowOnes[i] + 2 * colOnes[j] - n - m);
    }
    diff.push(row);
  }
  return diff;
}

