function onesMinusZeros(grid) {
  // Recount the row and the column from scratch for every cell.
  return grid.map((line, i) => line.map((_, j) => {
    let value = 0;
    for (const cell of grid[i]) value += cell === 1 ? 1 : -1;
    for (const r of grid) value += r[j] === 1 ? 1 : -1;
    return value;
  }));
}

