function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  let m, n;
  if (size === 'large') {
    const shape = rand();
    if (shape < 0.15) { m = 1; n = 100; }
    else if (shape < 0.3) { m = 100; n = 1; }
    else { m = int(60, 100); n = int(60, 100); }
  } else {
    m = int(1, 5);
    n = int(1, 5);
  }
  const density = [0, 0.2, 0.5, 0.8, 1][int(0, 4)];
  const grid = Array.from({ length: m }, () => Array.from({ length: n }, () => (rand() < density ? 1 : 0)));
  return [grid];
}
